@Test func debounceIssuesOneRequestForRapidTyping() {
  let scheduler = DispatchQueue.test          // virtual clock
  let api = SpyAPI()
  let model = SearchViewModel(api: api, scheduler: scheduler.eraseToAnyScheduler())

  model.query = "s"
  model.query = "sw"
  model.query = "swift"
  scheduler.advance(by: .milliseconds(299))
  #expect(api.callCount == 0)                 // nothing yet

